'use strict';
const G=window.Blackthorn,$=id=>document.getElementById(id),key='astra-open-world-v3';let campaign=null,busy=false,ready=false,cooldown=0,retry=null;
try{const saved=JSON.parse(localStorage.getItem(key));if(saved?.state?.version===3&&typeof saved.save==='string'&&G.classes[saved.state.cls])campaign=saved}catch{}
const safeList=(items,target)=>{target.replaceChildren();for(const text of items||[]){const p=document.createElement('p');p.textContent=text;target.append(p)}};
function logEntry(title,text,kind='story'){const div=document.createElement('div');div.className='entry '+kind;const h=document.createElement('h4');h.textContent=title;const p=document.createElement('p');p.textContent=text;div.append(h,p);return div}
function render(){const s=campaign?.state;$('creation').hidden=!!s;$('game').hidden=!s;if(!s)return;const c=G.classes[s.cls];$('heroName').textContent=s.name;$('heroClass').textContent=`LEVEL ${s.level} ${c.name.toUpperCase()} · ${s.xp} XP`;$('hp').textContent=s.hp+' / '+s.maxHp;$('ac').textContent=s.ac;$('health').style.width=s.hp/s.maxHp*100+'%';$('stats').replaceChildren();for(const[k,v]of Object.entries(c.stats)){const d=document.createElement('div');d.textContent=k;const b=document.createElement('b');b.textContent=(v>=0?'+':'')+v;d.append(b);$('stats').append(d)}$('pack').replaceChildren();const count=document.createElement('p');count.textContent=`${s.potions} potions · ${s.gold} gold`+(s.cls==='wizard'?` · ${s.slots}/3 spell slots`:'');$('pack').append(count);for(const item of s.inventory){const p=document.createElement('p');p.textContent=item;$('pack').append(p)}$('abilities').textContent=s.cls==='wizard'?'Describe spells in your spellbook or creative uses of Fire Bolt. Levelled spells consume a slot. A long rest restores slots.':s.cls==='rogue'?'Use stealth, misdirection and precise attacks. Describe your approach to earn advantage when the situation supports it.':'Use your strength, armour and longsword. Describe tactics, defensive manoeuvres or creative uses of the environment.';$('journal').replaceChildren();for(const q of s.quests){const li=document.createElement('li');li.textContent=q;$('journal').append(li)}safeList([...s.npcs,...s.places],$('worldnotes'));$('chapter').textContent=s.location;$('chapterNo').textContent='TURN '+s.turn;$('story').replaceChildren();if(!s.history.length)$('story').append(logEntry('The Dungeon Master',s.narrative));else for(const h of s.history){$('story').append(logEntry(s.name,h.action,'action'),logEntry('The Dungeon Master',h.narrative))}$('story').scrollTop=$('story').scrollHeight;$('enemy').hidden=true;const r=s.lastRoll;$('dice').textContent=r?r.die:'d20';$('roll').textContent=r?`${r.ability} · [${r.dice.join(', ')}] ${r.modifier>=0?'+':''}${r.modifier} = ${r.total} / DC ${r.dc} · ${r.success?'SUCCESS':'FAILURE'}${r.critical?' · CRITICAL':''}`:s.time;$('choices').replaceChildren();for(const suggestion of s.suggestions){const b=document.createElement('button');b.textContent=suggestion;b.onclick=()=>run(suggestion);b.disabled=busy||Date.now()<cooldown;$('choices').append(b)}$('potion').disabled=busy||!s.potions;$('rest').disabled=busy;$('newgame').disabled=busy;$('input').disabled=busy;$('command').querySelector('button').disabled=busy;try{localStorage.setItem(key,JSON.stringify(campaign));$('savestatus').textContent='PROGRESS SAVED ON THIS DEVICE'}catch{$('savestatus').textContent='SAVE UNAVAILABLE · KEEP THIS TAB OPEN'}}
async function call(body){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),105000);try{const response=await fetch('/api/turn',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:controller.signal});let data;try{data=await response.json()}catch{throw new Error('The dungeon master did not return a readable response. Your save is unchanged.')}if(!response.ok){if(data.retryAfter)cooldown=Date.now()+data.retryAfter*1000;throw new Error(data.error||'The dungeon master is unavailable. Please try again.')}if(!data.state||!data.save)throw new Error('The returned turn was incomplete. Your previous save is safe.');return data}finally{clearTimeout(timer)}}
async function run(action){action=action.trim();if(!campaign||busy||!action)return;if(Date.now()<cooldown){$('turnstatus').textContent=`The DM needs ${Math.ceil((cooldown-Date.now())/1000)} more seconds. Your action is still in the box.`;return}busy=true;render();$('turnstatus').textContent='The dungeon master considers your action…';const save=campaign.save;const requestId=retry?.action===action&&retry?.save===save?retry.requestId:crypto.randomUUID();retry={action,save,requestId};let timer=setTimeout(()=>{$('turnstatus').textContent='Rolling the dice and weaving the consequences…'},5000);try{const result=await call({action,save,requestId});campaign={state:result.state,save:result.save};retry=null;$('input').value='';$('turnstatus').textContent='';}catch(e){$('input').value=action;$('turnstatus').textContent=e.name==='AbortError'?'The turn took too long. Your save is unchanged. Try the action again.':e.message}finally{clearTimeout(timer);busy=false;render()}}
$('heroform').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;const b=e.target.querySelector('button[type="submit"]');b.disabled=true;$('availability').textContent='Preparing your campaign…';try{const result=await call({start:true,name:$('name').value,cls:new FormData(e.target).get('class')});campaign={state:result.state,save:result.save};render();$('game').scrollIntoView({behavior:'smooth',block:'start'})}catch(err){$('availability').textContent=err.message}finally{busy=false;b.disabled=false;render()}};
$('command').onsubmit=e=>{e.preventDefault();run($('input').value)};$('potion').onclick=()=>run('I drink one of my healing potions.');$('rest').onclick=()=>run('I look for a safe place and take a short rest.');$('newgame').onclick=()=>{if(busy||!confirm('Begin a new campaign? This replaces your open-world save.'))return;campaign=null;retry=null;try{localStorage.removeItem(key)}catch{}render();window.scrollTo({top:0,behavior:'smooth'})};for(const id of ['rules','credits'])$(id).onclick=()=>$('modal').showModal();$('close').onclick=()=>$('modal').close();render();
fetch('/api/turn').then(r=>r.json()).then(d=>{ready=!!d.configured;$('availability').textContent=ready?'The dungeon master is ready.':'Open-world mode is awaiting server configuration. You can still play the original adventure below.'}).catch(()=>{$('availability').textContent='Could not reach the dungeon master. Please try again shortly.'});
setInterval(()=>{if(cooldown&&Date.now()>=cooldown){cooldown=0;if(!busy){$('turnstatus').textContent='Ready when you are. Try your action again.';render()}}},1000);
